def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    scores = []
    total_non_dep = 0

    # New parameter settings (alternative)
    ALPHA = 0.35          # influence of route length (L-1)
    BETA = 0.30           # weight for per-node demand relative to route demand
    ATTENUATION_FACTOR = 0.8  # attenuation based on mean distance
    JITTER_SCALE = 0.25     # diversification jitter

    for route in current_solution:
        non_dep = [n for n in route if n != 0]
        L = len(non_dep)
        total_non_dep += L

        if L == 0:
            continue

        # Compute total route demand
        route_demand = 0.0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            prev_node = non_dep[idx - 1] if idx > 0 else None
            next_node = non_dep[idx + 1] if idx < L - 1 else None

            # Local saving term
            saving = 0.0
            if prev_node is not None and next_node is not None:
                saving = (distance_matrix[prev_node][node]
                          + distance_matrix[node][next_node]
                          - distance_matrix[prev_node][next_node])
                if saving < 0.0:
                    saving = 0.0
            else:
                # End-node bonus proportional to the edge length
                if prev_node is not None:
                    saving = 0.08 * distance_matrix[prev_node][node]
                elif next_node is not None:
                    saving = 0.08 * distance_matrix[node][next_node]
                else:
                    saving = 0.0

            # Mean distance to other nodes in the same route
            mean_distance = 0.0
            if L > 1:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    s += distance_matrix[node][other]
                mean_distance = s / (L - 1)
            else:
                mean_distance = 0.0

            demand = demands[node] if node < len(demands) else 0.0

            score = saving * (1.0 + ALPHA * (L - 1))

            if route_demand > 0.0:
                score += BETA * (demand / route_demand)

            attenuation = 1.0 / (1.0 + mean_distance * ATTENUATION_FACTOR)
            score *= attenuation

            perturb = rng.random() * JITTER_SCALE * (saving + mean_distance + 1.0)
            score += perturb

            if score < 0.0:
                score = 0.0

            scores.append((node, score))

    if total_non_dep == 0:
        k = 0
    else:
        frac = 0.08 + rng.random() * 0.12
        k = max(1, int(round(total_non_dep * frac)))
        if k > total_non_dep:
            k = total_non_dep

    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance = data['distance_matrix']
    demands = data['demands']

    scores_dict = {}
    for route in current_solution:
        for idx, node in enumerate(route):
            pred = route[idx - 1] if idx > 0 else None
            succ = route[idx + 1] if idx < len(route) - 1 else None

            if pred is not None and succ is not None:
                delta = distance[pred][node] + distance[node][succ] - distance[pred][succ]
            elif pred is not None:
                delta = distance[pred][node]
            elif succ is not None:
                delta = distance[node][succ]
            else:
                delta = 0.0

            d = demands[node] if node < len(demands) else 0
            score = delta * 1.0 + d * 0.5

            if node in scores_dict:
                if score > scores_dict[node]:
                    scores_dict[node] = score
            else:
                scores_dict[node] = score

    total_nodes = len(scores_dict)
    if total_nodes == 0:
        return [], 0

    temp = []
    for node, sc in scores_dict.items():
        temp.append((node, sc, rng.random()))
    temp.sort(key=lambda x: (-x[1], x[2]))
    scores = [(node, sc) for node, sc, _ in temp]

    k = max(1, int(0.25 * total_nodes))
    return scores, k

def destroy_scoring(current_solution, data, rng):
    distance_matrix = data['distance_matrix']
    demands = data.get('demands', [])
    vehicle_caps = data.get('vehicle_capacities', [])
    cap = max(vehicle_caps) if vehicle_caps else 0

    # Build anchors: first non-depot node in each route
    anchors = []
    for route in current_solution:
        anchor = None
        if route:
            for node in route:
                if node is not None and node != 0:
                    anchor = node
                    break
        anchors.append(anchor)

    scores = []
    total_nodes = 0

    for ri, route in enumerate(current_solution):
        if not route:
            continue

        # Non-depot nodes in this route
        non_dep = [n for n in route if (n is not None and n != 0)]
        m = len(non_dep)
        if m == 0:
            continue

        # Route demand
        route_demand = 0
        for n in non_dep:
            if n < len(demands):
                route_demand += demands[n]

        for idx, node in enumerate(non_dep):
            total_nodes += 1

            # Intra-route dispersion: average distance to other non-depot nodes in this route
            if m <= 1:
                intra_avg = 0.0
            else:
                s = 0.0
                for other in non_dep:
                    if other == node:
                        continue
                    if node < len(distance_matrix) and other < len(distance_matrix[node]):
                        d = distance_matrix[node][other]
                    else:
                        d = 0.0
                    s += d
                intra_avg = s / (m - 1)

            # Anchor distance: distance to nearest anchor in other routes
            anchor_dist = None
            for aj, anchor in enumerate(anchors):
                if aj == ri:
                    continue
                if anchor is None:
                    continue
                if node < len(distance_matrix) and anchor < len(distance_matrix[node]):
                    d = distance_matrix[node][anchor]
                else:
                    d = 0.0
                if anchor_dist is None or d < anchor_dist:
                    anchor_dist = d
            anchor_term = anchor_dist if anchor_dist is not None else 0.0

            # Demand term
            demand = demands[node] if node < len(demands) else 0

            # Slack (route pressure)
            slack = cap - route_demand
            if slack < 0:
                slack = 0
            ratio_slack = (slack / cap) if cap > 0 else 0.0

            # Small jitter for diversification
            jitter = (rng.random() * 0.15) - 0.075

            # Composite score (higher means more likely to be removed)
            score = (0.45 * intra_avg) + (0.30 * anchor_term) + (0.15 * (1.0 / (1.0 + demand))) + (0.10 * (1.0 - ratio_slack)) + jitter

            scores.append((node, score))

    if total_nodes == 0:
        k = 0
    else:
        # Choose a diversification-friendly fraction of nodes to remove
        frac = 0.25 + rng.random() * 0.35  # between 0.25 and 0.60
        max_k = max(1, total_nodes // 2)
        k = int(rng.integers(1, max_k + 1))
        if k > total_nodes:
            k = total_nodes

    return scores, k

def score_state(state):
    score = 0.0
    base_penalty = 2.5
    decay_factor = 0.8
    for lane in state:
        highest_priority = None
        depth_penalty = 0
        for i in range(len(lane)):
            if lane[i] != 0:
                if highest_priority is not None and lane[i] < highest_priority:
                    score += base_penalty ** depth_penalty * (decay_factor ** depth_penalty)
                highest_priority = lane[i]
                depth_penalty += 1
    return score

def score_state(state):
    score = 0
    for lane in state:
        max_val = 0
        for idx, unit in enumerate(lane):
            if unit != 0:
                if unit < max_val:
                    score += (idx + 1) * (6 - unit)
                max_val = unit
    return score

def score_state(state):
    score = 0
    for lane in state:
        max_val = 0
        block_count = 0
        lane_length = len(lane)
        is_sorted = True

        for idx, load in enumerate(lane):
            if load != 0:
                if max_val > load:
                    block_count += 1
                    higher_loads_above = sum(1 for i in range(idx + 1, lane_length) if lane[i] < load)
                    penalty = (block_count * higher_loads_above * idx) / lane_length
                    score += penalty
                    is_sorted = False
                else:
                    block_count = 0
                max_val = load

        if not is_sorted:
            score += sum(load for load in lane if load != 0) / lane_length

        if lane and lane[0] == max_val:
            score -= 1

    return score

def score_state(state):
    score = 0.0
    for lane in state:
        non_zero_elements = [load for load in lane if load != 0]
        n = len(non_zero_elements)
        max_length_factor = 1.0 / (n + 1e-6)  # Avoid division by zero
        penalty = 0
        for i in range(n - 1):
            if non_zero_elements[i] > non_zero_elements[i + 1]:
                penalty += (i + 1) * non_zero_elements[i]
        score += penalty * max_length_factor
    return score

def score_state(state):
    score = 0
    max_stack_height = max(len(stack) for stack in state)

    for stack in state:
        n = len(stack)
        if n == 0:
            continue

        out_of_order_count = 0
        total_value = 0

        for i in range(n - 1):
            if stack[i] > stack[i + 1]:
                out_of_order_count += 1
                total_value += (stack[i] + stack[i + 1])

        if out_of_order_count > 0:
            average_value = total_value / (out_of_order_count * 2)
            score += out_of_order_count * average_value * ((n - out_of_order_count) / max_stack_height)

    return  score

def score_state(state):
    score = 0
    for lane in state:
        non_empty_start = next((i for i, x in enumerate(lane) if x != 0), len(lane))
        for i in range(non_empty_start, len(lane)):
            for j in range(i + 1, len(lane)):
                if lane[i] > lane[j]:
                    score += (len(lane) - j)
    return score

def score_state(state):
    score = 0
    for lane in state:
        blocking_count = 0
        seen_non_zero = False
        for load in reversed(lane):
            if load != 0:
                seen_non_zero = True
            if seen_non_zero and load == 0:
                blocking_count += 1
        score += blocking_count * (len(lane) - blocking_count)
    return score

def score_state(state):
    score = 0
    for stack in state:
        n = len(stack)
        for i in range(n - 1):
            for j in range(i + 1, n):
                if stack[i] > stack[j]:
                    score += (stack[i] + stack[j]) / (i + 1 + j + 1)
    return  score

def score_state(state):
    N = len(state)
    score = 0
    misplaced_tiles = set()

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance
                if i != goal_i or j != goal_j:
                    misplaced_tiles.add((i, j))

    for (i, j) in misplaced_tiles:
        value = state[i][j]
        goal_i, goal_j = divmod(value - 1, N)
        min_penalty = float('inf')

        # Check neighbors for penalty adjustment with adaptive weight
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < N and 0 <= nj < N and state[ni][nj] != 0:
                n_value = state[ni][nj]
                n_goal_i, n_goal_j = divmod(n_value - 1, N)
                penalty = abs(ni - goal_i) + abs(nj - goal_j)
                if penalty == 0:
                    min_penalty = 0
                    break
                else:
                    # Adaptive weight factor based on distance to edge with reduced weight
                    distance_to_edge = min(i, N - i - 1, j, N - j - 1)
                    weight_factor = (distance_to_edge / (N // 2)) if distance_to_edge > 0 else 0.5
                    min_penalty = min(min_penalty, penalty * weight_factor)

        score += min_penalty

    # Blockage penalty between tiles that block each other's goal paths with increased factor
    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0 and (state[i][j] - 1) // N == i]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(len(row_tiles) - 1):
            for l in range(k + 1, len(row_tiles)):
                if row_tiles[k][1] > row_tiles[l][1]:
                    score += 2 * (l - k)

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0 and (state[i][j] - 1) % N == j]
        col_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[0])
        for k in range(len(col_tiles) - 1):
            for l in range(k + 1, len(col_tiles)):
                if col_tiles[k][1] > col_tiles[l][1]:
                    score += 2 * (l - k)

    return score

def score_state(state):
    N = len(state)
    score = 0
    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_inversions(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        inversions = 0
        for k in range(len(sorted_positions) - 1):
            if sorted_positions[k][1] > sorted_positions[k + 1][1]:
                inversions += 1
        return inversions

    misplaced_tiles = sum(1 for i in range(N) for j in range(N) if state[i][j] != 0 and state[i][j] != (i * N + j + 1))

    for positions in row_positions:
        score += count_inversions(positions) * 3

    for positions in col_positions:
        score += count_inversions(positions) * 3

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += (distance / N) * 2

    return score

def score_state(state):
    N = len(state)
    score = 0
    total_distance = 0
    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                total_distance += distance
                score += distance * (distance + 1) / 2
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    def count_misplaced_neighbors(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        misplaced = 0
        for k in range(1, len(sorted_positions)):
            if sorted_positions[k][1] < sorted_positions[k - 1][1]:
                misplaced += 1
        return misplaced

    def count_obstructed_paths(state, i, j, target_i, target_j):
        obstructed = 0
        for x in range(min(i, target_i) + 1, max(i, target_i)):
            if state[x][j] != 0:
                obstructed += 1 / (x - min(i, target_i))
        for y in range(min(j, target_j) + 1, max(j, target_j)):
            if state[i][y] != 0:
                obstructed += 1 / (y - min(j, target_j))
        return obstructed

    for positions in row_positions:
        score += count_misplaced_neighbors(positions) * 3

    for positions in col_positions:
        score += count_misplaced_neighbors(positions) * 2

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                obstructed_paths = count_obstructed_paths(state, i, j, target_i, target_j)
                score += obstructed_paths

    score += total_distance / (N * 2)

    return score

def score_state(state):
    N = len(state)
    score = 0
    misplaced_tiles_row = [set() for _ in range(N)]
    misplaced_tiles_col = [set() for _ in range(N)]

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                distance = abs(i - target_i) + abs(j - target_j)
                score += distance
                if i != target_i and abs(i - target_i) > 1:
                    misplaced_tiles_row[i].add((value, j))
                if j != target_j and abs(j - target_j) > 1:
                    misplaced_tiles_col[j].add((value, i))

    for row_set in misplaced_tiles_row:
        conflicts = len(row_set) - 1
        score += conflicts * 0.75

    for col_set in misplaced_tiles_col:
        conflicts = len(col_set) - 1
        score += conflicts * 0.75

    return score

