def score_state(state):
    N = len(state)
    score = 0
    row_positions = [set() for _ in range(N)]
    col_positions = [set() for _ in range(N)]

    def count_inversions(positions):
        sorted_positions = sorted(positions, key=lambda x: x[0])
        inversions = 0
        for k in range(len(sorted_positions) - 1):
            if sorted_positions[k][1] > sorted_positions[k + 1][1]:
                inversions += 1
        return inversions

    def count_blocking_tiles(state, i, j, target_i, target_j):
        blocking = 0
        if i < target_i:
            for x in range(i + 1, target_i):
                if state[x][j] != 0:
                    blocking += 1
        elif i > target_i:
            for x in range(target_i + 1, i):
                if state[x][j] != 0:
                    blocking += 1
        if j < target_j:
            for y in range(j + 1, target_j):
                if state[i][y] != 0:
                    blocking += 1
        elif j > target_j:
            for y in range(target_j + 1, j):
                if state[i][y] != 0:
                    blocking += 1
        return blocking

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                score += abs(i - target_i) + abs(j - target_j)
                row_positions[target_i].add((value, j))
                col_positions[target_j].add((value, i))

    for positions in row_positions:
        score += count_inversions(positions) * 3

    for positions in col_positions:
        score += count_inversions(positions) * 3

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                target_i, target_j = divmod(value - 1, N)
                blocking_tiles = count_blocking_tiles(state, i, j, target_i, target_j)
                score += blocking_tiles * 4

    return score

def score_state(state):
    N = len(state)
    target_positions = {i: (i // N, i % N) for i in range(1, N * N)}
    score = 0

    for row_idx in range(N):
        for col_idx in range(N):
            tile = state[row_idx][col_idx]
            if tile != 0:
                target_row, target_col = target_positions[tile]
                score += abs(row_idx - target_row) + abs(col_idx - target_col)

    return score

def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

    # Block-based penalty
    for i in range(0, N-1, 2):
        for j in range(0, N-1, 2):
            block = [
                state[i][j], state[i][j+1],
                state[i+1][j], state[i+1][j+1]
            ]
            sorted_block = sorted(block)
            if block != sorted_block:
                score += 1

    return score

def score_state(state):
    N = len(state)
    score = 0

    for i in range(N):
        for j in range(N):
            value = state[i][j]
            if value != 0:
                goal_i, goal_j = divmod(value - 1, N)
                manhattan_distance = abs(i - goal_i) + abs(j - goal_j)
                score += manhattan_distance

                # Check for linear conflicts in rows
                if i == goal_i:
                    for k in range(N):
                        other_value = state[i][k]
                        if other_value != 0:
                            other_goal_i, other_goal_j = divmod(other_value - 1, N)
                            if other_goal_i == goal_i and k > j and other_goal_j < goal_j:
                                score += 2

                # Check for linear conflicts in columns
                if j == goal_j:
                    for k in range(N):
                        other_value = state[k][j]
                        if other_value != 0:
                            other_goal_i, other_goal_j = divmod(other_value - 1, N)
                            if other_goal_j == goal_j and k > i and other_goal_i < goal_i:
                                score += 2

    for i in range(N):
        row_tiles = [(state[i][j], j) for j in range(N) if state[i][j] != 0 and (state[i][j] - 1) // N == i]
        row_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[1])
        for k in range(1, len(row_tiles)):
            if row_tiles[k][1] < row_tiles[k - 1][1]:
                score += (N - row_tiles[k][1]) ** 2

    for j in range(N):
        col_tiles = [(state[i][j], i) for i in range(N) if state[i][j] != 0 and (state[i][j] - 1) % N == j]
        col_tiles.sort(key=lambda x: divmod(x[0] - 1, N)[0])
        for k in range(1, len(col_tiles)):
            if col_tiles[k][1] < col_tiles[k - 1][1]:
                score += (N - col_tiles[k][1]) ** 2

    return score
